allocator class can be specified as a template argument to
[`fmt::basic_memory_buffer`](#basic_memory_buffer):
</code></pre> <pre><code>using custom_memory_buffer = 
  fmt::basic_memory_buffer&lt;char, fmt::inline_buffer_size, custom_allocator&gt;;
</code></pre> <pre><code>    using custom_memory_buffer = 
      fmt::basic_memory_buffer&lt;char, fmt::inline_buffer_size, custom_allocator&gt;;
</code></pre> <p>也可以编写使用自定义分配器的格式化函数：</p> <pre><code>It is also possible to write a formatting function that uses a custom
allocator:
</code></pre> <pre><code>using custom_string =
  std::basic_string&lt;char, std::char_traits&lt;char&gt;, custom_allocator&gt;;
</code></pre> <pre><code>    using custom_string =
      std::basic_string&lt;char, std::char_traits&lt;char&gt;, custom_allocator&gt;;
</code></pre> <pre><code>auto vformat(custom_allocator alloc, fmt::string_view fmt,
             fmt::format_args args) -&gt; custom_string {
  auto buf = custom_memory_buffer(alloc);
  fmt::vformat_to(std::back_inserter(buf), fmt, args);
  return custom_string(buf.data(), buf.size(), alloc);
}
</code></pre> <pre><code>    auto vformat(custom_allocator alloc, fmt::string_view fmt,
                 fmt::format_args args) -&gt; custom_string {
      auto buf = custom_memory_buffer(alloc);
      fmt::vformat_to(std::back_inserter(buf), fmt, args);
      return custom_string(buf.data(), buf.size(), alloc);
    }
</code></pre> <pre><code>template &lt;typename ...Args&gt;
auto format(custom_allocator alloc, fmt::string_view fmt,
            const Args&amp; ... args) -&gt; custom_string {
  return vformat(alloc, fmt, fmt::make_format_args(args...));
}
</code></pre> <pre><code>    template &lt;typename ...Args&gt;
    auto format(custom_allocator alloc, fmt::string_view fmt,
